// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GetHealthz Liveness probe
	// (GET /healthz)
	GetHealthz(w http.ResponseWriter, r *http.Request)
	// GetReadyz Readiness probe
	// (GET /readyz)
	GetReadyz(w http.ResponseWriter, r *http.Request)
	// ListApiKeys List the workspace's API keys
	// (GET /v1/api-keys)
	ListApiKeys(w http.ResponseWriter, r *http.Request, params ListApiKeysParams)
	// CreateApiKey Create an API key
	// (POST /v1/api-keys)
	CreateApiKey(w http.ResponseWriter, r *http.Request)
	// RevokeApiKey Revoke an API key
	// (DELETE /v1/api-keys/{id})
	RevokeApiKey(w http.ResponseWriter, r *http.Request, id ApiKeyId)
	// CreateApplication Create a consumer application in the development environment
	// (POST /v1/applications)
	CreateApplication(w http.ResponseWriter, r *http.Request)
	// ArchiveApplication Archive an application
	// (DELETE /v1/applications/{applicationId})
	ArchiveApplication(w http.ResponseWriter, r *http.Request, applicationId ApplicationId)
	// GetApplication Read an application
	// (GET /v1/applications/{applicationId})
	GetApplication(w http.ResponseWriter, r *http.Request, applicationId ApplicationId)
	// UpdateApplication Change an application's settings
	// (PATCH /v1/applications/{applicationId})
	UpdateApplication(w http.ResponseWriter, r *http.Request, applicationId ApplicationId)
	// CreateApplicationApiKey Create an API key bound to one application
	// (POST /v1/applications/{applicationId}/api-keys)
	CreateApplicationApiKey(w http.ResponseWriter, r *http.Request, applicationId ApplicationId)
	// ListApplicationEndpoints List an application's endpoints
	// (GET /v1/applications/{applicationId}/endpoints)
	ListApplicationEndpoints(w http.ResponseWriter, r *http.Request, applicationId ApplicationId)
	// CreateEndpoint Register an endpoint
	// (POST /v1/applications/{applicationId}/endpoints)
	CreateEndpoint(w http.ResponseWriter, r *http.Request, applicationId ApplicationId)
	// ListApplicationMessages List an application's messages
	// (GET /v1/applications/{applicationId}/messages)
	ListApplicationMessages(w http.ResponseWriter, r *http.Request, applicationId ApplicationId, params ListApplicationMessagesParams)
	// SubmitMessage Submit an event
	// (POST /v1/applications/{applicationId}/messages)
	SubmitMessage(w http.ResponseWriter, r *http.Request, applicationId ApplicationId, params SubmitMessageParams)
	// ListAuditEvents List the workspace's audit events
	// (GET /v1/audit)
	ListAuditEvents(w http.ResponseWriter, r *http.Request, params ListAuditEventsParams)
	// ListDeliveryAttempts List the attempts of a delivery
	// (GET /v1/deliveries/{deliveryId}/attempts)
	ListDeliveryAttempts(w http.ResponseWriter, r *http.Request, deliveryId DeliveryId)
	// CancelDelivery Cancel a delivery
	// (POST /v1/deliveries/{deliveryId}/cancel)
	CancelDelivery(w http.ResponseWriter, r *http.Request, deliveryId DeliveryId)
	// ReplayDelivery Replay a failed or cancelled delivery
	// (POST /v1/deliveries/{deliveryId}/replay)
	ReplayDelivery(w http.ResponseWriter, r *http.Request, deliveryId DeliveryId, params ReplayDeliveryParams)
	// ArchiveEndpoint Archive an endpoint
	// (DELETE /v1/endpoints/{endpointId})
	ArchiveEndpoint(w http.ResponseWriter, r *http.Request, endpointId EndpointId)
	// GetEndpoint Read an endpoint
	// (GET /v1/endpoints/{endpointId})
	GetEndpoint(w http.ResponseWriter, r *http.Request, endpointId EndpointId)
	// UpdateEndpoint Change an endpoint
	// (PATCH /v1/endpoints/{endpointId})
	UpdateEndpoint(w http.ResponseWriter, r *http.Request, endpointId EndpointId)
	// PauseEndpoint Pause an endpoint
	// (POST /v1/endpoints/{endpointId}/pause)
	PauseEndpoint(w http.ResponseWriter, r *http.Request, endpointId EndpointId)
	// ResumeEndpoint Resume an endpoint
	// (POST /v1/endpoints/{endpointId}/resume)
	ResumeEndpoint(w http.ResponseWriter, r *http.Request, endpointId EndpointId)
	// RotateEndpointSecret Rotate the signing secret
	// (POST /v1/endpoints/{endpointId}/rotate-secret)
	RotateEndpointSecret(w http.ResponseWriter, r *http.Request, endpointId EndpointId)
	// SendTestMessage Send a test delivery to an endpoint
	// (POST /v1/endpoints/{endpointId}/test)
	SendTestMessage(w http.ResponseWriter, r *http.Request, endpointId EndpointId)
	// ListEnvironments List the workspace's environments
	// (GET /v1/environments)
	ListEnvironments(w http.ResponseWriter, r *http.Request)
	// CreateEnvironment Create an environment
	// (POST /v1/environments)
	CreateEnvironment(w http.ResponseWriter, r *http.Request)
	// ListEnvironmentApplications List an environment's applications
	// (GET /v1/environments/{environmentId}/applications)
	ListEnvironmentApplications(w http.ResponseWriter, r *http.Request, environmentId EnvironmentId)
	// CreateEnvironmentApplication Create a consumer application in an environment
	// (POST /v1/environments/{environmentId}/applications)
	CreateEnvironmentApplication(w http.ResponseWriter, r *http.Request, environmentId EnvironmentId)
	// ListEnvironmentMessages List an environment's messages across its applications
	// (GET /v1/environments/{environmentId}/messages)
	ListEnvironmentMessages(w http.ResponseWriter, r *http.Request, environmentId EnvironmentId, params ListEnvironmentMessagesParams)
	// GetEnvironmentOverview Overview tiles of an environment
	// (GET /v1/environments/{environmentId}/overview)
	GetEnvironmentOverview(w http.ResponseWriter, r *http.Request, environmentId EnvironmentId)
	// GetMe Who am I
	// (GET /v1/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// GetNotificationPreferences My alert email preference
	// (GET /v1/me/notification-preferences)
	GetNotificationPreferences(w http.ResponseWriter, r *http.Request)
	// UpdateNotificationPreferences Set my alert email preference
	// (PUT /v1/me/notification-preferences)
	UpdateNotificationPreferences(w http.ResponseWriter, r *http.Request)
	// ListMembers List the workspace's members
	// (GET /v1/members)
	ListMembers(w http.ResponseWriter, r *http.Request)
	// SetMemberRole Make a member a developer or a viewer
	// (PUT /v1/members/{userId}/role)
	SetMemberRole(w http.ResponseWriter, r *http.Request, userId string)
	// GetMessage Inspect a message and its deliveries
	// (GET /v1/messages/{messageId})
	GetMessage(w http.ResponseWriter, r *http.Request, messageId MessageId)
	// GetMessagePayload Read a message's payload
	// (GET /v1/messages/{messageId}/payload)
	GetMessagePayload(w http.ResponseWriter, r *http.Request, messageId MessageId)
	// ListNotifications List my notifications in the active workspace
	// (GET /v1/notifications)
	ListNotifications(w http.ResponseWriter, r *http.Request, params ListNotificationsParams)
	// MarkNotificationRead Mark a notification read
	// (POST /v1/notifications/{notificationId}/read)
	MarkNotificationRead(w http.ResponseWriter, r *http.Request, notificationId NotificationId)
	// GetWorkspaceLimits Quotas and usage of the active workspace
	// (GET /v1/workspaces/current/limits)
	GetWorkspaceLimits(w http.ResponseWriter, r *http.Request)
}

// ServerInterfaceWrapper converts contexts to parameters.
type ServerInterfaceWrapper struct {
	Handler            ServerInterface
	HandlerMiddlewares []MiddlewareFunc
	ErrorHandlerFunc   func(w http.ResponseWriter, r *http.Request, err error)
}

type MiddlewareFunc func(http.Handler) http.Handler

// GetHealthz operation middleware
func (siw *ServerInterfaceWrapper) GetHealthz(w http.ResponseWriter, r *http.Request) {

	handler := http.Handler(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		siw.Handler.GetHealthz(w, r)
	}))

	for _, middleware := range siw.HandlerMiddlewares {
		handler = middleware(handler)
	}

	handler.ServeHTTP(w, r)
}

// GetReadyz operation middleware
func (siw *ServerInterfaceWrapper) GetReadyz(w http.ResponseWriter, r *http.Request) {

	handler := http.Handler(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		siw.Handler.GetReadyz(w, r)
	}))

	for _, middleware := range siw.HandlerMiddlewares {
		handler = middleware(handler)
	}

	handler.ServeHTTP(w, r)
}

